// Dashboard logic. Data: data.js (generated by main.ts). Farm plans use the
// SAME templates as main.ts farmStepsFor, so detail view and board.json agree.
const $ = (id) => document.getElementById(id);
function reconName(slug) { return slug.split("-").map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(" "); }
function fmtMoney(x) {
  if (x < 10) return "$" + x.toFixed(2);
  if (x < 1000) return "$" + Math.round(x);
  if (x < 1e6) return "$" + (x / 1e3).toFixed(1).replace(/\.0$/, "") + "k";
  if (x < 1e9) return "$" + (x / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
  return "$" + (x / 1e9).toFixed(2) + "B";
}
function parseSci(s) { return parseFloat(s); }
// Decode ROWS: slug,name,impliedSci,oddsInt,catIdx,growthInt,ageDays,tvlSci,chainIdx,cheapIdx
const BOARD = ROWS.split("|").map((line, i) => {
  const f = line.split(",");
  const tvl = parseSci(f[7]);
  return { slug: f[0], name: f[1] || reconName(f[0]), rank: i + 1, ev: parseSci(f[2]),
    odds: +f[3] / 100, cat: CATS[+f[4]], growth: +f[5] / 100, age: +f[6], tvl,
    multiple: Math.exp(META.intercept + META.slope * Math.log(tvl)) / tvl,
    chain: CHAINS[+f[8]], cheap: CHAINS[+f[9]], wl: WL.includes(f[0]) };
});
const REFROWS = REF.split("|").map((line) => { const f = line.split(","); return { slug: f[0], name: reconName(f[0]), mcap: parseSci(f[1]) }; });
// Gas: planning estimates, NOT live quotes — same table as main.ts.
const GAS = { Ethereum: 6, Arbitrum: 0.3, Base: 0.15, Optimism: 0.2, Solana: 0.02, Avalanche: 0.3, BSC: 0.2, Polygon: 0.05 };
const gasOf = (c) => GAS[c] ?? 0.5;
function cheapestChain(chains) { let b = chains[0]; for (const c of chains) if (gasOf(c) < gasOf(b)) b = c; return b; }
function catAction(cat) {
  const c = cat || "";
  if (c === "Dexs") return { verb: "Swap dan sediakan likuiditas", noun: "swap" };
  if (c === "Lending") return { verb: "Supply aset dan pinjam", noun: "supply" };
  if (c === "Yield" || c === "Yield Aggregator" || c === "Farm") return { verb: "Deposit ke vault dan compound hasil", noun: "deposit" };
  if (c === "Liquid Staking" || c === "Liquid Restaking" || c === "Restaking" || c === "Staking Pool") return { verb: "Stake dan restake", noun: "stake" };
  if (c === "Bridge" || c === "Cross Chain Bridge" || c === "Canonical Bridge") return { verb: "Bridge aset antar rantai", noun: "bridge" };
  if (c === "Derivatives" || c === "Options" || c === "Options Vault" || c === "Basis Trading") return { verb: "Buka posisi dan kelola margin", noun: "posisi" };
  if (c === "CDP" || c === "CDP Manager") return { verb: "Buka vault dan mint stablecoin", noun: "vault" };
  if (c === "RWA") return { verb: "Beli dan tahan aset tokenisasi", noun: "posisi RWA" };
  if (c === "Prediction Market") return { verb: "Pasang posisi di pasar prediksi", noun: "posisi" };
  if (c === "Launchpad") return { verb: "Stake dan ikuti penjualan token", noun: "partisipasi" };
  if (c === "Payments" || c === "Crypto Card Issuer") return { verb: "Pakai protokol untuk pembayaran rutin", noun: "pembayaran" };
  if (c === "Insurance" || c === "Risk Curators") return { verb: "Beli cover dan sediakan underwriting", noun: "cover" };
  if (c === "NFT Marketplace") return { verb: "Beli dan jual NFT", noun: "transaksi NFT" };
  if (c === "Stablecoin Issuer" || c === "Algo-Stables" || c === "Dual-Token Stablecoin") return { verb: "Mint dan tahan stablecoin", noun: "mint" };
  return { verb: "Gunakan protokol secara rutin", noun: "aktivitas" };
}
// Same farm-plan templates as main.ts — keep in sync.
function farmStepsFor(p, ev) {
  const chain = p.chains[0] || "Ethereum";
  const gas = gasOf(chain);
  const cheap = cheapestChain(p.chains);
  const act = catAction(p.cat);
  const alt = cheap !== chain ? ` Alternatif murah: ${cheap} (~$${gasOf(cheap)}/tx).` : "";
  const txN = [3, 5, 7];
  const cost = txN.map((n) => n * gas + 3);
  const fmtC = (x) => (x < 10 ? "$" + x.toFixed(2) : "$" + Math.round(x));
  const medPct = (cost[1] / Math.max(ev, 1)) * 100;
  const verdict = medPct < 5 ? "layak di semua tier — biaya jauh di bawah expected value"
    : medPct < 20 ? "layak di tier menengah/besar, marginal di tier kecil"
    : "mahal relatif terhadap expected value — hanya tier besar bila yakin, tier kecil sebaiknya skip";
  return [
    `Siapkan dompet ${chain}-ready (baru, khusus farming), simpan seed phrase offline, lalu bridge dana ke ${chain} — biaya bridge ~$3 (planning estimate, bukan kuotasi live), waktu 10-30 menit.${alt}`,
    `${act.verb} di ${p.name} senilai $100 (kecil) / $1.000 (menengah) / $10.000 (besar) dalam 1 transaksi — gas ~$${gas} di ${chain}, waktu 5 menit. Simpan hash transaksi sebagai bukti aktivitas.`,
    `Ulangi ${act.noun} 1x per minggu selama 4-8 minggu (total 4-8 transaksi, gas ~$${gas} tiap transaksi, 5 menit per minggu) agar riwayat aktivitas terlihat konsisten, bukan sekali jalan.`,
    `Catat tiap tanggal, jumlah, dan hash transaksi di spreadsheet; cek posisi di explorer ${chain} tiap 2 minggu (10 menit) dan pastikan dana tetap aktif, bukan ditarik setelah transaksi pertama.`,
    `Kelola risiko: jangan pakai dana kebutuhan harian, jangan klik tautan airdrop dari DM atau iklan, dan siapkan exit — penarikan penuh butuh 1 transaksi (~$${gas}) plus waktu tunggu protokol bila ada.`,
    `Perkiraan biaya ${fmtC(cost[0])} (kecil) / ${fmtC(cost[1])} (menengah) / ${fmtC(cost[2])} (besar); expected value ${fmtMoney(ev)}; biaya tier menengah = ${medPct < 0.1 ? "<0,1" : medPct.toFixed(1)}% dari expected value — ${verdict}.`,
  ];
}
// Stage-2 factors, same formula as main.ts.
function stage2Factors(g, age) {
  const raw = 0.5 * META.growthCoef * g + 0.5 * META.ageCoef * Math.log(Math.max(1, age));
  const adj = Math.max(-0.35, Math.min(0.35, raw));
  const s = raw === 0 ? 1 : adj / raw;
  return { gF: Math.exp(0.5 * META.growthCoef * g * s), mF: Math.exp(0.5 * META.ageCoef * Math.log(Math.max(1, age)) * s) };
}
let sortKey = "rank", sortDir = 1;
const bySlug = new Map(BOARD.map((r) => [r.slug, r]));
function renderKpis() {
  const tot = BOARD.reduce((a, r) => a + r.ev, 0);
  const wlN = BOARD.filter((r) => r.wl).length;
  const med = BOARD[Math.floor(BOARD.length / 2)].ev;
  $("kpis").innerHTML = [
    ["614", "pre-token protocols ranked"], [fmtMoney(tot), "total implied value (sum)"],
    [fmtMoney(BOARD[0].ev), "rank #1: " + BOARD[0].name], [fmtMoney(med), "median implied value"],
    [wlN + " / 40", "watchlist covered"], ["19%", "global launch odds (144/758)"],
  ].map(([b, s]) => `<div class="kpi"><b>${b}</b><span>${s}</span></div>`).join("");
}
function filtered() {
  const q = $("q").value.trim().toLowerCase();
  const cat = $("cat").value, wl = $("wl").checked, mo = +$("minodds").value / 100;
  let rows = BOARD.filter((r) =>
    (!q || r.name.toLowerCase().includes(q) || r.slug.includes(q)) &&
    (!cat || r.cat === cat) && (!wl || r.wl) && r.odds >= mo);
  const k = sortKey;
  rows = [...rows].sort((a, b) => {
    const av = k === "name" ? a.name : k === "cat" ? a.cat : a[k];
    const bv = k === "name" ? b.name : k === "cat" ? b.cat : b[k];
    return (av < bv ? -1 : av > bv ? 1 : 0) * sortDir;
  });
  return rows;
}
function renderRows() {
  const rows = filtered();
  $("count").textContent = rows.length + " of 614 shown";
  $("rows").innerHTML = rows.slice(0, 200).map((r) => `<tr data-slug="${r.slug}">
    <td>${r.rank}</td><td>${r.wl ? '<span class="wl">★ </span>' : ""}${r.name}</td><td>${r.cat}</td>
    <td class="num">${fmtMoney(r.tvl)}</td>
    <td class="num">${(r.growth * 100).toFixed(1)}%</td><td class="num">${r.age}d</td>
    <td class="num">${Math.round(r.odds * 100)}%</td><td class="num ev">${fmtMoney(r.ev)}</td></tr>`).join("") +
    (rows.length > 200 ? `<tr><td colspan="8">Showing first 200 — narrow the filter to see more.</td></tr>` : "");
  document.querySelectorAll("#rows tr[data-slug]").forEach((tr) => tr.addEventListener("click", () => showDetail(tr.dataset.slug)));
}
function showDetail(slug) {
  const r = bySlug.get(slug); if (!r) return;
  const chains = r.cheap === r.chain ? [r.chain] : [r.chain, r.cheap];
  const p = { slug: r.slug, name: r.name, cat: r.cat, chains };
  const f = stage2Factors(r.growth, r.age);
  const tvl = r.tvl;
  const fair = tvl * r.multiple * f.gF * f.mF;
  $("detail").innerHTML = `<h3>#${r.rank} ${r.name} ${r.wl ? '<span class="wl">★ watchlist</span>' : ""}</h3>
  <div class="kstrip">
    <div><b>${fmtMoney(tvl)}</b><span>TVL</span></div>
    <div><b>${(r.growth * 100).toFixed(1)}%</b><span>growth 7d</span></div>
    <div><b>${r.age}d</b><span>age</span></div>
    <div><b>${Math.round(r.odds * 100)}%</b><span>token odds</span></div>
    <div><b>${fmtMoney(r.ev)}</b><span>expected value</span></div>
  </div>
  <div class="decomp">TVL ${fmtMoney(tvl)} × multiple ${r.multiple.toFixed(2)} × growth ${f.gF.toFixed(2)} × maturity ${f.mF.toFixed(2)} = fair value ${fmtMoney(fair)}; × odds ${Math.round(r.odds * 100)}% = <b>expected value ${fmtMoney(r.ev)}</b>. Fair value is what the token would be worth if launched at peers' multiples; odds are the chance it launches at all.</div>
  <h4>Farm plan — 3 tiers</h4><ol class="farm">${farmStepsFor(p, r.ev).map((s) => `<li>${s}</li>`).join("")}</ol>`;
  $("detail").scrollIntoView({ behavior: "smooth", block: "nearest" });
}
function renderModel() {
  const v = META.val;
  $("model").innerHTML = `<table><tbody>
  <tr><td>Stage 1 (fitted at runtime, n=${META.liveN})</td><td>log(mcap) = ${META.intercept} + ${META.slope}·log(TVL) — ${META.mode} intercept</td></tr>
  <tr><td>Stage 2 (n=${META.stage2N}, fitted with intercept c0=${META.c0})</td><td>growth coef ${META.growthCoef}, log-age coef ${META.ageCoef}; slopes shrunk ×0.5, total adjustment clamped ±0.35 in log; c0 is a subset-mean offset and is not applied</td></tr>
  <tr><td>Held-out seed 1 (70/30)</td><td>median |log error| ${v.h1Pooled} (R² ${v.h1PooledR2}) vs baseline ${v.baseH1}; category-intercept variant ${v.h1Cat}</td></tr>
  <tr><td>Held-out seed 2 (70/30)</td><td>median |log error| ${v.h2Pooled} (R² ${v.h2PooledR2}) vs baseline ${v.baseH2}; category-intercept variant ${v.h2Cat}</td></tr>
  <tr><td>Walk-forward (earliest 70% train, latest 30% test, dated protocols)</td><td>median |log error| ${v.wfPooled} (R² ${v.wfPooledR2}) vs baseline ${v.baseWf}; category-intercept variant ${v.wfCat}</td></tr>
  <tr><td>Why pooled wins</td><td>Category intercepts raise in-sample R² but do not beat pooled on unseen data, so the simpler pooled model is used. Growth and age move the multiple only slightly in the data, so their effect is kept small.</td></tr>
  <tr><td>Token odds</td><td>Global launch rate ${Math.round(META.globalOdds * 100)}% (144 of 758). Category rate shrunk toward global; age-band factor shrunk toward 1; odds clamped to 2–50%.</td></tr>
  <tr><td>What the score means</td><td>Implied value = fair value × odds (expected value). It is not a prediction of whether or when a token launches.</td></tr>
  </tbody></table>`;
}
function renderRef() {
  $("refrows").innerHTML = REFROWS.map((r, i) => `<tr><td>${i + 1}</td><td>${r.name}</td><td class="num">${fmtMoney(r.mcap)}</td></tr>`).join("");
}
function init() {
  const sel = $("cat");
  CATS.forEach((c) => { const o = document.createElement("option"); o.value = c; o.textContent = c; sel.appendChild(o); });
  ["q", "cat", "wl", "minodds"].forEach((id) => $(id).addEventListener("input", () => { if (id === "minodds") $("minoddsV").textContent = $("minodds").value + "%"; renderRows(); }));
  document.querySelectorAll("th[data-s]").forEach((th) => th.addEventListener("click", () => {
    const k = th.dataset.s;
    if (sortKey === k) sortDir *= -1; else { sortKey = k; sortDir = 1; }
    renderRows();
  }));
  document.querySelectorAll(".tabs button").forEach((b) => b.addEventListener("click", () => {
    document.querySelectorAll(".tabs button").forEach((x) => x.classList.remove("on"));
    b.classList.add("on");
    $("tab-board").hidden = b.dataset.tab !== "board";
    $("tab-model").hidden = b.dataset.tab !== "model";
    $("tab-ref").hidden = b.dataset.tab !== "ref";
  }));
  renderKpis(); renderRows(); renderModel(); renderRef();
  showDetail(BOARD[0].slug);
}
init();
